IF (SELECT COUNT(*) FROM @EventInput) <> 2240
    THROW 52011, 'Expected the sourced goal and card events.', 1;

IF EXISTS (
    SELECT 1
    FROM @EventInput AS input
    LEFT JOIN dbo.person AS person
        ON person.name = input.player_name
    LEFT JOIN dbo.player AS player
        ON player.person_id = person.person_id
    WHERE player.person_id IS NULL
)
    THROW 52012, 'Every event participant must resolve to a player profile.', 1;

IF EXISTS (SELECT 1 FROM dbo.goal) OR EXISTS (SELECT 1 FROM dbo.card)
    THROW 52013, 'Goal and card events are already loaded.', 1;

BEGIN TRY
    BEGIN TRANSACTION;

    INSERT INTO dbo.match_event (match_id, event_no, minute)
    SELECT match_map.match_id, input.event_no, input.minute
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id;

    INSERT INTO dbo.event_player (match_id, event_no, player_id, [role])
    SELECT match_map.match_id, input.event_no, player.person_id, input.[role]
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    INNER JOIN dbo.person AS person
        ON person.name = input.player_name
    INNER JOIN dbo.player AS player
        ON player.person_id = person.person_id;

    INSERT INTO dbo.goal (match_id, event_no, goal_type)
    SELECT match_map.match_id, input.event_no, input.goal_type
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    WHERE input.event_type = N'goal';

    INSERT INTO dbo.card (match_id, event_no, colour)
    SELECT match_map.match_id, input.event_no, input.card_colour
    FROM @EventInput AS input
    INNER JOIN @MatchMap AS match_map
        ON match_map.source_match_id = input.source_match_id
    WHERE input.event_type = N'card';

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
